/* ===================== Engels woordenboek, ronde 2: de wedstrijd ===================== */
// De momenten (game/wedstrijd/momenten.js), het wedstrijdverslag en de meldingen tijdens de wedstrijd (wedstrijd.js).
// * = een naam, een voornaamwoord of een stuk zin dat er los in komt; # = een getal (core/taal.js).

// Een kans voor een teamgenoot (momenten.js assistKans): "<intro> <naam>, die hem binnenschuift!" of "..., maar hij mist."
const INTRO = {
  'Een steekpass door de verdediging op':'A through ball splits the defence for', 'Je legt de bal breed op':'You square the ball to', 'Een brutaal hakje voor':'A cheeky backheel for',
  'Onbaatzuchtig! Je legt hem breed op':'Unselfish! You square it to', 'Je lange bal valt precies voor de voeten van':'Your long ball drops right at the feet of', 'Een diepe bal in de loop van':'A ball in behind into the path of',
  'Je voorzet draait precies op het hoofd van':'Your cross curls right onto the head of', 'Je kopt de bal slim terug naar':'You cleverly head the ball back to', 'Je verlengt de corner bij de eerste paal naar':'You flick the corner on at the near post to',
  'Je kopt de bal precies door op':'You head the ball perfectly on to', 'Je steekbal snijdt de verdediging open voor':'Your through ball cuts the defence open for', 'Een zalige chip over de verdediging voor':'A delightful chip over the defence for',
  'Je lange bal komt precies bij':'Your long ball finds', 'Je legt hem breed op':'You square it to', 'Je lange bal valt op het hoofd van':'Your long ball lands on the head of', 'Je lange trap komt precies bij':'Your long kick finds',
  'Je gooit hem snel uit. Een flitsende counter, en de bal komt bij':'You throw it out quickly. A lightning counter, and the ball reaches',
};
const KANS = {};
for (const [nl, en] of Object.entries(INTRO)){
  KANS[nl + ' *, die hem binnenschuift!'] = en + ' *, who slots it home!';
  KANS[nl + ' *, maar * mist.'] = en + ' *, but * misses.';
}

